-- 015_degree_and_ai.sql: degree tracker and the AI / planning suite (from "Higher-Ed ERD and RBAC schema" PDF, 6 Oct).
-- Extends semester_campus_portals.sql (schema semester). After 014. NOT executed or parsed. Same conventions: (tenant_id, id) keys,
-- tenant-safe composite FKs, ENABLE + FORCE RLS, no PUBLIC grants; reads added below follow 014's helpers.
BEGIN;
SET LOCAL search_path = semester, public;
SET LOCAL lock_timeout = '5s';

-- ------------------------------------------------ degree tracker
CREATE TABLE catalog_versions (tenant_id uuid NOT NULL REFERENCES institutions(id), id uuid NOT NULL DEFAULT gen_random_uuid(), code text NOT NULL, effective_from date NOT NULL, published_at timestamptz, PRIMARY KEY (tenant_id, id), UNIQUE (tenant_id, code));
CREATE TABLE degree_requirement_sets (tenant_id uuid NOT NULL, id uuid NOT NULL DEFAULT gen_random_uuid(), catalog_version_id uuid NOT NULL, program_id uuid NOT NULL, published_at timestamptz, PRIMARY KEY (tenant_id, id),
  FOREIGN KEY (tenant_id, catalog_version_id) REFERENCES catalog_versions(tenant_id, id), FOREIGN KEY (tenant_id, program_id) REFERENCES programs(tenant_id, id), UNIQUE (tenant_id, catalog_version_id, program_id));
CREATE TABLE requirement_nodes (tenant_id uuid NOT NULL, id uuid NOT NULL DEFAULT gen_random_uuid(), set_id uuid NOT NULL, parent_id uuid, label text NOT NULL, sort_order integer NOT NULL, node_type text NOT NULL CHECK (node_type IN ('group', 'all_of', 'n_of', 'credits', 'course')), PRIMARY KEY (tenant_id, id),
  FOREIGN KEY (tenant_id, set_id) REFERENCES degree_requirement_sets(tenant_id, id), FOREIGN KEY (tenant_id, parent_id) REFERENCES requirement_nodes(tenant_id, id));
CREATE TABLE requirement_rules (tenant_id uuid NOT NULL, id uuid NOT NULL DEFAULT gen_random_uuid(), node_id uuid NOT NULL, rule_type text NOT NULL CHECK (rule_type IN ('min_credits', 'min_courses', 'min_grade', 'min_gpa', 'residency', 'no_double_count', 'choose_n')), rule jsonb NOT NULL, PRIMARY KEY (tenant_id, id), FOREIGN KEY (tenant_id, node_id) REFERENCES requirement_nodes(tenant_id, id));
CREATE TABLE requirement_course_sets (tenant_id uuid NOT NULL, id uuid NOT NULL DEFAULT gen_random_uuid(), node_id uuid NOT NULL, course_id uuid NOT NULL, PRIMARY KEY (tenant_id, id), FOREIGN KEY (tenant_id, node_id) REFERENCES requirement_nodes(tenant_id, id), FOREIGN KEY (tenant_id, course_id) REFERENCES courses(tenant_id, id), UNIQUE (tenant_id, node_id, course_id));
CREATE TABLE student_requirement_bindings (tenant_id uuid NOT NULL, id uuid NOT NULL DEFAULT gen_random_uuid(), person_id uuid NOT NULL, set_id uuid NOT NULL, bound_at timestamptz NOT NULL DEFAULT now(), authority text NOT NULL CHECK (authority IN ('sis', 'native')), PRIMARY KEY (tenant_id, id),
  FOREIGN KEY (tenant_id, person_id) REFERENCES people(tenant_id, id), FOREIGN KEY (tenant_id, set_id) REFERENCES degree_requirement_sets(tenant_id, id));
CREATE TABLE academic_credit_items (tenant_id uuid NOT NULL, id uuid NOT NULL DEFAULT gen_random_uuid(), person_id uuid NOT NULL, kind text NOT NULL CHECK (kind IN ('course', 'transfer', 'exam', 'other')), course_id uuid, external_label text, credits numeric NOT NULL CHECK (credits >= 0), grade text, term_code text, source_connection_id uuid, external_id text, last_synced_at timestamptz,
  PRIMARY KEY (tenant_id, id), FOREIGN KEY (tenant_id, person_id) REFERENCES people(tenant_id, id));
CREATE TABLE credit_equivalencies (tenant_id uuid NOT NULL, id uuid NOT NULL DEFAULT gen_random_uuid(), external_label text NOT NULL, course_id uuid NOT NULL, effective_from date NOT NULL, effective_until date, approved_by uuid NOT NULL, PRIMARY KEY (tenant_id, id), FOREIGN KEY (tenant_id, course_id) REFERENCES courses(tenant_id, id));
CREATE TABLE requirement_exceptions (tenant_id uuid NOT NULL, id uuid NOT NULL DEFAULT gen_random_uuid(), person_id uuid NOT NULL, node_id uuid NOT NULL, exception_type text NOT NULL CHECK (exception_type IN ('substitution', 'waiver')), credit_item_id uuid, approved_by uuid NOT NULL, approved_at timestamptz NOT NULL, reason text NOT NULL,
  PRIMARY KEY (tenant_id, id), FOREIGN KEY (tenant_id, person_id) REFERENCES people(tenant_id, id), FOREIGN KEY (tenant_id, node_id) REFERENCES requirement_nodes(tenant_id, id));
CREATE TABLE degree_audit_runs (tenant_id uuid NOT NULL, id uuid NOT NULL DEFAULT gen_random_uuid(), person_id uuid NOT NULL, set_id uuid NOT NULL, engine_version text NOT NULL, inputs_hash text NOT NULL, authority_mode text NOT NULL, scenario_plan_id uuid, run_at timestamptz NOT NULL DEFAULT now(), official_match text CHECK (official_match IN ('matches', 'differs', 'not_compared')),
  PRIMARY KEY (tenant_id, id), FOREIGN KEY (tenant_id, person_id) REFERENCES people(tenant_id, id), FOREIGN KEY (tenant_id, set_id) REFERENCES degree_requirement_sets(tenant_id, id));
CREATE TABLE degree_audit_results (tenant_id uuid NOT NULL, id uuid NOT NULL DEFAULT gen_random_uuid(), run_id uuid NOT NULL, node_id uuid NOT NULL,
  state text NOT NULL CHECK (state IN ('met', 'met_if_in_progress_passes', 'not_met', 'unresolved', 'planned')), explanation text NOT NULL, PRIMARY KEY (tenant_id, id),
  FOREIGN KEY (tenant_id, run_id) REFERENCES degree_audit_runs(tenant_id, id), FOREIGN KEY (tenant_id, node_id) REFERENCES requirement_nodes(tenant_id, id), UNIQUE (tenant_id, run_id, node_id));
CREATE TABLE degree_audit_allocations (tenant_id uuid NOT NULL, id uuid NOT NULL DEFAULT gen_random_uuid(), run_id uuid NOT NULL, node_id uuid NOT NULL, credit_item_id uuid NOT NULL, credits_applied numeric NOT NULL, PRIMARY KEY (tenant_id, id),
  FOREIGN KEY (tenant_id, run_id) REFERENCES degree_audit_runs(tenant_id, id), FOREIGN KEY (tenant_id, credit_item_id) REFERENCES academic_credit_items(tenant_id, id));
-- One credit item satisfies one requirement per run unless a rule explicitly allows sharing (checked by the engine, which must
-- solve constraints rather than allocate greedily).
CREATE UNIQUE INDEX one_allocation_per_credit ON degree_audit_allocations(tenant_id, run_id, credit_item_id);
CREATE TABLE academic_plan_versions (tenant_id uuid NOT NULL, id uuid NOT NULL DEFAULT gen_random_uuid(), person_id uuid NOT NULL, label text NOT NULL, created_by uuid NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), shared_with_advisor boolean NOT NULL DEFAULT false, PRIMARY KEY (tenant_id, id), FOREIGN KEY (tenant_id, person_id) REFERENCES people(tenant_id, id));
CREATE TABLE planned_course_items (tenant_id uuid NOT NULL, id uuid NOT NULL DEFAULT gen_random_uuid(), plan_id uuid NOT NULL, course_id uuid NOT NULL, term_code text NOT NULL, assumption text, PRIMARY KEY (tenant_id, id), FOREIGN KEY (tenant_id, plan_id) REFERENCES academic_plan_versions(tenant_id, id));
CREATE TABLE advisor_plan_reviews (tenant_id uuid NOT NULL, id uuid NOT NULL DEFAULT gen_random_uuid(), plan_id uuid NOT NULL, advisor_person_id uuid NOT NULL, comment text, acknowledged_at timestamptz, PRIMARY KEY (tenant_id, id), FOREIGN KEY (tenant_id, plan_id) REFERENCES academic_plan_versions(tenant_id, id));
CREATE TABLE graduation_applications (tenant_id uuid NOT NULL, id uuid NOT NULL DEFAULT gen_random_uuid(), person_id uuid NOT NULL, term_code text NOT NULL, status text NOT NULL CHECK (status IN ('draft', 'submitted', 'under_review', 'approved', 'denied', 'withdrawn')), PRIMARY KEY (tenant_id, id), FOREIGN KEY (tenant_id, person_id) REFERENCES people(tenant_id, id));
CREATE TABLE degree_certifications (tenant_id uuid NOT NULL, id uuid NOT NULL DEFAULT gen_random_uuid(), graduation_application_id uuid NOT NULL, audit_run_id uuid NOT NULL, certified_by uuid NOT NULL, certified_at timestamptz NOT NULL, PRIMARY KEY (tenant_id, id),
  FOREIGN KEY (tenant_id, graduation_application_id) REFERENCES graduation_applications(tenant_id, id), FOREIGN KEY (tenant_id, audit_run_id) REFERENCES degree_audit_runs(tenant_id, id));

-- ------------------------------------------------ study, planning and AI (student-controlled; never a risk profile by default)
CREATE TABLE study_plans (tenant_id uuid NOT NULL, id uuid NOT NULL DEFAULT gen_random_uuid(), person_id uuid NOT NULL, goal text NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY (tenant_id, id), FOREIGN KEY (tenant_id, person_id) REFERENCES people(tenant_id, id));
CREATE TABLE study_sessions (tenant_id uuid NOT NULL, id uuid NOT NULL DEFAULT gen_random_uuid(), plan_id uuid NOT NULL, starts_at timestamptz NOT NULL, minutes integer NOT NULL CHECK (minutes > 0), target text, completed boolean NOT NULL DEFAULT false, self_reported_confidence smallint CHECK (self_reported_confidence BETWEEN 1 AND 5), PRIMARY KEY (tenant_id, id), FOREIGN KEY (tenant_id, plan_id) REFERENCES study_plans(tenant_id, id));
CREATE TABLE availability_windows (tenant_id uuid NOT NULL, id uuid NOT NULL DEFAULT gen_random_uuid(), person_id uuid NOT NULL, weekday smallint NOT NULL CHECK (weekday BETWEEN 0 AND 6), starts_local time NOT NULL, ends_local time NOT NULL, kind text NOT NULL CHECK (kind IN ('free', 'work', 'athletics', 'travel', 'other')), PRIMARY KEY (tenant_id, id), FOREIGN KEY (tenant_id, person_id) REFERENCES people(tenant_id, id));
CREATE TABLE practice_attempts (tenant_id uuid NOT NULL, id uuid NOT NULL DEFAULT gen_random_uuid(), person_id uuid NOT NULL, concept text NOT NULL, correct boolean NOT NULL, attempted_at timestamptz NOT NULL DEFAULT now(), source_reference text, PRIMARY KEY (tenant_id, id), FOREIGN KEY (tenant_id, person_id) REFERENCES people(tenant_id, id));
CREATE TABLE assistant_preferences (tenant_id uuid NOT NULL, person_id uuid NOT NULL, quiet_start time, quiet_end time, daily_nudge_limit smallint NOT NULL DEFAULT 3, history_enabled boolean NOT NULL DEFAULT false, PRIMARY KEY (tenant_id, person_id), FOREIGN KEY (tenant_id, person_id) REFERENCES people(tenant_id, id));
CREATE TABLE ai_runs (tenant_id uuid NOT NULL, id uuid NOT NULL DEFAULT gen_random_uuid(), person_id uuid NOT NULL, role text NOT NULL CHECK (role IN ('executive_assistant', 'executive_advisor', 'academic_advisor', 'tutor', 'course_guide')),
  model text NOT NULL, policy_version text NOT NULL, course_ai_rule text, started_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY (tenant_id, id), FOREIGN KEY (tenant_id, person_id) REFERENCES people(tenant_id, id));
CREATE TABLE ai_source_references (tenant_id uuid NOT NULL, id uuid NOT NULL DEFAULT gen_random_uuid(), run_id uuid NOT NULL, source_type text NOT NULL, source_id uuid, freshness timestamptz, PRIMARY KEY (tenant_id, id), FOREIGN KEY (tenant_id, run_id) REFERENCES ai_runs(tenant_id, id));
CREATE TABLE ai_policy_decisions (tenant_id uuid NOT NULL, id uuid NOT NULL DEFAULT gen_random_uuid(), run_id uuid NOT NULL, requested text NOT NULL, decision text NOT NULL CHECK (decision IN ('allow', 'deny', 'refer')), reason_code text NOT NULL, PRIMARY KEY (tenant_id, id), FOREIGN KEY (tenant_id, run_id) REFERENCES ai_runs(tenant_id, id));
CREATE TABLE ai_recommendations (tenant_id uuid NOT NULL, id uuid NOT NULL DEFAULT gen_random_uuid(), run_id uuid NOT NULL, proposed_option text NOT NULL, supporting_records jsonb NOT NULL, alternatives jsonb NOT NULL, assumptions jsonb NOT NULL, uncertainties jsonb NOT NULL, approvals_needed jsonb NOT NULL, next_reversible_action text NOT NULL,
  PRIMARY KEY (tenant_id, id), FOREIGN KEY (tenant_id, run_id) REFERENCES ai_runs(tenant_id, id));
-- Exact approval → execution binding: the approved payload hash must equal the executed payload hash.
CREATE TABLE action_approvals (tenant_id uuid NOT NULL, id uuid NOT NULL DEFAULT gen_random_uuid(), recommendation_id uuid, person_id uuid NOT NULL, action_type text NOT NULL CHECK (action_type IN ('add_to_cart', 'create_task', 'book_appointment', 'draft_email', 'send_email', 'submit_form')), payload jsonb NOT NULL, payload_hash text NOT NULL, approved_at timestamptz NOT NULL DEFAULT now(), expires_at timestamptz NOT NULL,
  PRIMARY KEY (tenant_id, id), FOREIGN KEY (tenant_id, person_id) REFERENCES people(tenant_id, id), CHECK (expires_at <= approved_at + interval '1 hour'));
CREATE TABLE action_execution_results (tenant_id uuid NOT NULL, id uuid NOT NULL DEFAULT gen_random_uuid(), approval_id uuid NOT NULL, executed_payload_hash text NOT NULL, outcome text NOT NULL CHECK (outcome IN ('succeeded', 'failed', 'unknown')), verified_at timestamptz, verification_note text, PRIMARY KEY (tenant_id, id),
  FOREIGN KEY (tenant_id, approval_id) REFERENCES action_approvals(tenant_id, id), UNIQUE (tenant_id, approval_id));
CREATE FUNCTION semester.check_execution_binding() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
  IF NOT EXISTS (SELECT 1 FROM semester.action_approvals a WHERE a.tenant_id = NEW.tenant_id AND a.id = NEW.approval_id AND a.payload_hash = NEW.executed_payload_hash AND a.expires_at > now()) THEN
    RAISE EXCEPTION USING ERRCODE = '42501', MESSAGE = 'EXECUTION_NOT_APPROVED'; END IF;
  RETURN NEW;
END $$;
CREATE TRIGGER execution_binding BEFORE INSERT ON action_execution_results FOR EACH ROW EXECUTE FUNCTION semester.check_execution_binding();

DO $$ DECLARE t text; BEGIN
  FOREACH t IN ARRAY ARRAY['catalog_versions', 'degree_requirement_sets', 'requirement_nodes', 'requirement_rules', 'requirement_course_sets', 'student_requirement_bindings', 'academic_credit_items', 'credit_equivalencies', 'requirement_exceptions', 'degree_audit_runs', 'degree_audit_results', 'degree_audit_allocations', 'academic_plan_versions', 'planned_course_items', 'advisor_plan_reviews', 'graduation_applications', 'degree_certifications', 'study_plans', 'study_sessions', 'availability_windows', 'practice_attempts', 'assistant_preferences', 'ai_runs', 'ai_source_references', 'ai_policy_decisions', 'ai_recommendations', 'action_approvals', 'action_execution_results'] LOOP
    EXECUTE format('ALTER TABLE semester.%I ENABLE ROW LEVEL SECURITY', t); EXECUTE format('ALTER TABLE semester.%I FORCE ROW LEVEL SECURITY', t); EXECUTE format('REVOKE ALL ON semester.%I FROM PUBLIC, anon', t);
  END LOOP;
END $$;
GRANT SELECT ON semester.degree_audit_runs, semester.degree_audit_results, semester.academic_plan_versions, semester.planned_course_items, semester.advisor_plan_reviews, semester.study_plans, semester.study_sessions, semester.availability_windows, semester.practice_attempts, semester.assistant_preferences, semester.ai_recommendations TO authenticated;
CREATE POLICY own ON semester.degree_audit_runs FOR SELECT TO authenticated USING (semester.is_me(tenant_id, person_id) OR semester.advises(tenant_id, person_id));
CREATE POLICY own ON semester.degree_audit_results FOR SELECT TO authenticated USING (EXISTS (SELECT 1 FROM semester.degree_audit_runs r WHERE r.tenant_id = degree_audit_results.tenant_id AND r.id = degree_audit_results.run_id AND (semester.is_me(r.tenant_id, r.person_id) OR semester.advises(r.tenant_id, r.person_id))));
CREATE POLICY own ON semester.academic_plan_versions FOR SELECT TO authenticated USING (semester.is_me(tenant_id, person_id) OR (shared_with_advisor AND semester.advises(tenant_id, person_id)));
CREATE POLICY own ON semester.planned_course_items FOR SELECT TO authenticated USING (EXISTS (SELECT 1 FROM semester.academic_plan_versions p WHERE p.tenant_id = planned_course_items.tenant_id AND p.id = planned_course_items.plan_id AND (semester.is_me(p.tenant_id, p.person_id) OR (p.shared_with_advisor AND semester.advises(p.tenant_id, p.person_id)))));
CREATE POLICY own ON semester.advisor_plan_reviews FOR SELECT TO authenticated USING (EXISTS (SELECT 1 FROM semester.academic_plan_versions p WHERE p.tenant_id = advisor_plan_reviews.tenant_id AND p.id = advisor_plan_reviews.plan_id AND (semester.is_me(p.tenant_id, p.person_id) OR semester.advises(p.tenant_id, p.person_id))));
-- Personal learning data: owner only. Advisors and instructors never see study sessions, practice attempts or preferences.
CREATE POLICY own ON semester.study_plans FOR SELECT TO authenticated USING (semester.is_me(tenant_id, person_id));
CREATE POLICY own ON semester.study_sessions FOR SELECT TO authenticated USING (EXISTS (SELECT 1 FROM semester.study_plans p WHERE p.tenant_id = study_sessions.tenant_id AND p.id = study_sessions.plan_id AND semester.is_me(p.tenant_id, p.person_id)));
CREATE POLICY own ON semester.availability_windows FOR SELECT TO authenticated USING (semester.is_me(tenant_id, person_id));
CREATE POLICY own ON semester.practice_attempts FOR SELECT TO authenticated USING (semester.is_me(tenant_id, person_id));
CREATE POLICY own ON semester.assistant_preferences FOR SELECT TO authenticated USING (semester.is_me(tenant_id, person_id));
CREATE POLICY own ON semester.ai_recommendations FOR SELECT TO authenticated USING (EXISTS (SELECT 1 FROM semester.ai_runs r WHERE r.tenant_id = ai_recommendations.tenant_id AND r.id = ai_recommendations.run_id AND semester.is_me(r.tenant_id, r.person_id)));
COMMIT;
